From 25b51c41bb4113756334f5c162f4510279200a69 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:45:13 +0100
Subject: [PATCH] applets/taskmanager: add backward cycling and new window
 shortcuts

The Meta+number shortcuts could only activate an entry or cycle through
its group's windows forward. This adds per-entry actions that cycle the
group backward (Meta+Ctrl+number) and open a new window of the entry.

BUG: 464321
---
 applets/taskmanager/backend.cpp           | 24 ++++++++++++++++++-----
 applets/taskmanager/backend.h             |  4 +++-
 applets/taskmanager/qml/code/TaskTools.js |  7 ++-----
 applets/taskmanager/qml/main.qml          | 17 +++++++++++++---
 4 files changed, 38 insertions(+), 14 deletions(-)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..e444191b33 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -612,7 +612,21 @@ void Backend::setupShortcuts()
             action->setText(i18n("Activate Task Manager Entry %1", entryNumber));
             KGlobalAccel::setGlobalShortcut(action, entryNumber < 10 ? QKeySequence(Qt::META | key) : QKeySequence());
             QObject::connect(action, &QAction::triggered, collection, [i](bool) {
-                dispatchActivateTaskAtIndex(i);
+                dispatchTaskAtIndex(&Backend::activateTaskAtIndexRequested, i);
+            });
+
+            QAction *backwardAction = collection->addAction(QStringLiteral("activate task manager entry %1 backward").arg(QString::number(entryNumber)));
+            backwardAction->setText(i18n("Cycle Backward Through Task Manager Entry %1", entryNumber));
+            KGlobalAccel::setGlobalShortcut(backwardAction, entryNumber < 10 ? QKeySequence(Qt::META | Qt::CTRL | key) : QKeySequence());
+            QObject::connect(backwardAction, &QAction::triggered, collection, [i](bool) {
+                dispatchTaskAtIndex(&Backend::activateTaskAtIndexBackwardRequested, i);
+            });
+
+            QAction *newInstanceAction = collection->addAction(QStringLiteral("new instance of task manager entry %1").arg(QString::number(entryNumber)));
+            newInstanceAction->setText(i18n("Open New Window of Task Manager Entry %1", entryNumber));
+            KGlobalAccel::setGlobalShortcut(newInstanceAction, QKeySequence());
+            QObject::connect(newInstanceAction, &QAction::triggered, collection, [i](bool) {
+                dispatchTaskAtIndex(&Backend::newInstanceOfTaskAtIndexRequested, i);
             });
         }
     });
@@ -644,13 +658,13 @@ Backend *Backend::findTargetBackend()
     return fallback;
 }

-void Backend::dispatchActivateTaskAtIndex(int index)
+void Backend::dispatchTaskAtIndex(void (Backend::*signal)(int), int index)
 {
     // Prefer the same priority order as the other task shortcuts:
     // 1. Non-screen-filtered taskbar with the active task
     // 2. Screen-filtered taskbar with the active task
     if (auto *target = findTargetBackend()) {
-        Q_EMIT target->activateTaskAtIndexRequested(index);
+        Q_EMIT(target->*signal)(index);
         return;
     }

@@ -660,7 +674,7 @@ void Backend::dispatchActivateTaskAtIndex(int index)
     Backend *fallback = nullptr;
     for (auto *instance : std::as_const(s_instances)) {
         if (!instance->m_showsOnlyCurrentScreen) {
-            Q_EMIT instance->activateTaskAtIndexRequested(index);
+            Q_EMIT(instance->*signal)(index);
             return;
         }
         if (!fallback) {
@@ -668,7 +682,7 @@ void Backend::dispatchActivateTaskAtIndex(int index)
         }
     }
     if (fallback) {
-        Q_EMIT fallback->activateTaskAtIndexRequested(index);
+        Q_EMIT(fallback->*signal)(index);
     }
 }

diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..9fb46ac26d 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -87,6 +87,8 @@ Q_SIGNALS:
     void showsOnlyCurrentScreenChanged();

     void activateTaskAtIndexRequested(int index);
+    void activateTaskAtIndexBackwardRequested(int index);
+    void newInstanceOfTaskAtIndexRequested(int index);
     void activatePreviousTaskRequested();
     void activateNextTaskRequested();
     void moveActiveTaskBackwardRequested();
@@ -98,7 +100,7 @@ private Q_SLOTS:
 private:
     static void setupShortcuts();
     static Backend *findTargetBackend();
-    static void dispatchActivateTaskAtIndex(int index);
+    static void dispatchTaskAtIndex(void (Backend::*signal)(int), int index);
     static void dispatchActivatePreviousTask();
     static void dispatchActivateNextTask();
     static void dispatchMoveActiveTaskBackward();
diff --git a/applets/taskmanager/qml/code/TaskTools.js b/applets/taskmanager/qml/code/TaskTools.js
index 8f8adadd6f..e34a81bff8 100644
--- a/applets/taskmanager/qml/code/TaskTools.js
+++ b/applets/taskmanager/qml/code/TaskTools.js
@@ -116,7 +116,7 @@ function groupTopTask(childTaskList, attribute, tasks) {
     return topTaskIndex;
 }

-function activateTask(index, model, modifiers, task, plasmoid, tasks, windowViewAvailable) {
+function activateTask(index, model, modifiers, task, plasmoid, tasks, windowViewAvailable, backward = false) {
     if (modifiers & Qt.ShiftModifier) {
         tasks.tasksModel.requestNewInstance(index);
         return;
@@ -150,10 +150,7 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView
                     const childTask = childTaskList[j];
                     if (tasks.tasksModel.data(childTask, TaskManager.AbstractTasksModel.IsActive)) {
                         // Found the current task. Activate the next one
-                        let nextTask = j + 1;
-                        if (nextTask >= childTaskList.length) {
-                            nextTask = 0;
-                        }
+                        const nextTask = (j + (backward ? -1 : 1) + childTaskList.length) % childTaskList.length;
                         tasks.tasksModel.requestActivate(childTaskList[nextTask]);
                         break;
                     }
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..6361e8f8da 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -249,7 +249,18 @@ PlasmoidItem {
         }

         onActivateTaskAtIndexRequested: index => {
-            tasks.activateTaskAtIndex(index);
+            tasks.activateTaskAtIndex(index, false);
+        }
+
+        onActivateTaskAtIndexBackwardRequested: index => {
+            tasks.activateTaskAtIndex(index, true);
+        }
+
+        onNewInstanceOfTaskAtIndexRequested: index => {
+            const task = taskRepeater.itemAt(index) as Task;
+            if (task) {
+                tasksModel.requestNewInstance(task.modelIndex());
+            }
         }

         onActivatePreviousTaskRequested: () => {
@@ -561,10 +572,10 @@ PlasmoidItem {
         }
     }

-    function activateTaskAtIndex(index: int): void {
+    function activateTaskAtIndex(index: int, backward: bool): void {
         const task = taskRepeater.itemAt(index) as Task;
         if (task) {
-            TaskManagerApplet.TaskTools.activateTask(task.modelIndex(), task.model, null, task, Plasmoid, this, effectWatcher.registered);
+            TaskManagerApplet.TaskTools.activateTask(task.modelIndex(), task.model, null, task, Plasmoid, this, effectWatcher.registered, backward);
         }
     }

